[
  {
    "title": "missing-kick-foot",
    "claim": "In Image #13, Asmongold’s extended kicking leg ends at an open trouser cuff with no visible foot, while HasanAbi stands clear of it.",
    "reason": "The incomplete silhouette makes the kick’s reach difficult to judge.",
    "suggest": "Repair the extended front-kick sprite to include the bare foot and a complete ankle-to-toe silhouette."
  },
  {
    "title": "fraction-baseline-mismatch",
    "claim": "In Image #8, the denominator of HasanAbi’s 2½ HUD score drops below both the whole number and fighter name, and the result banner repeats this oversized stacked fraction.",
    "reason": "Players must decipher a vertically broken score instead of reading it immediately.",
    "suggest": "Render the half point with a baseline-aligned ½ glyph on the same line as the whole number in both locations."
  },
  {
    "title": "block-effect-below-contact",
    "claim": "In Image #12, the blue block particles cluster around HasanAbi’s belt and legs while Asmongold’s extended kick meets his upper torso.",
    "reason": "The effect identifies a different contact location from the fighters’ visible pose.",
    "suggest": "Anchor the initial block burst where the kicking limb meets the defender, then let trailing particles fall from that point."
  },
  {
    "title": "tiny-phone-labels",
    "claim": "In Image #3, the fighter-name and joystick-caption capital letters are approximately 8 CSS px tall at the stated 390px viewport scale.",
    "reason": "These labels are difficult to read during play on a phone.",
    "suggest": "Set their font size to at least 18 CSS px, reduce letter spacing, and adjust HUD wrapping to accommodate the larger text."
  },
  {
    "title": "small-fighters-at-distance",
    "claim": "The fighters are approximately 130 CSS px tall in Image #22 versus approximately 200 CSS px in Image #3, despite the matching phone viewport and joystick layout.",
    "reason": "The smaller presentation makes attack poses and spacing harder to distinguish.",
    "suggest": "Raise the minimum portrait fighter height to approximately 160 CSS px and tighten camera framing around both fighters."
  }
]
